static int count=0;
static void Check(BOOL ok,NSString *name){if(!ok){NSLog(@"FAIL %@",name);exit(1);}count++;NSLog(@"PASS %@",name);}
static void Write(NSString *path,NSString *text){[NSFileManager.defaultManager createDirectoryAtPath:path.stringByDeletingLastPathComponent withIntermediateDirectories:YES attributes:nil error:nil];[text writeToFile:path atomically:YES encoding:NSUTF8StringEncoding error:nil];}
int main(int argc,const char *argv[]){@autoreleasepool{
 NSString *root=@(argv[1]);NSFileManager *fm=NSFileManager.defaultManager;[fm createDirectoryAtPath:root withIntermediateDirectories:YES attributes:nil error:nil];
 NSArray *rows=TFAIProviderRegistry();Check(rows.count==11,@"11 providers with original 8 retained");NSArray *old=@[@"chat",@"responses",@"anthropic",@"deepseek",@"gemini",@"qwen",@"siliconflow",@"openrouter"];Check([[[rows subarrayWithRange:NSMakeRange(0,8)] valueForKey:@"id"] isEqual:old],@"original provider order and identifiers preserved");
 for(NSDictionary *row in rows){Check([TFAIObservedCapabilities(@{})[@"text"] isEqual:@"unknown"],@"untested capabilities unknown");for(NSString *key in row[@"capabilities"])Check([row[@"capabilities"][key] isEqual:@"unknown"],@"catalog never claims observed support");}
 for(NSString *id in @[@"kimi",@"xai"]){NSDictionary *row=TFAIProvider(id);NSMutableDictionary *c=[row mutableCopy];c[@"protocol"]=id;c[@"model"]=@"example";Check([TFAIEndpoint(c,YES,nil).absoluteString isEqual:row[@"modelsURL"]],@"new provider uses official models endpoint");Check([TFAIEndpoint(c,NO,nil).path hasSuffix:@"/chat/completions"],@"new provider shares OpenAI-compatible wire");Check(TFAIRequestBody(@[@{@"role":@"user",@"content":@"test"}],c,@[],YES,nil)!=nil,@"new provider creates real chat body");}
 NSArray *cases=@[@[@"gemini",@"gemini-2.5-pro",@[@"auto",@"low",@"medium",@"high"]],@[@"gemini",@"gemini-3-pro",@[@"auto",@"low",@"high"]],@[@"gemini",@"gemini-3-flash",@[@"auto",@"minimal",@"low",@"medium",@"high"]],@[@"deepseek",@"deepseek-chat",@[@"auto",@"enabled"]],@[@"qwen",@"qwen3-plus",@[@"auto",@"enabled"]],@[@"qwen",@"qwen3-instruct",@[@"auto"]],@[@"chat",@"gpt-5.2",@[@"auto",@"low",@"medium",@"high",@"xhigh"]],@[@"chat",@"gpt-6-sol",@[@"auto",@"low",@"medium",@"high",@"xhigh",@"ultra"]],@[@"chat",@"unknown-model",@[@"auto"]]];
 for(NSArray *c in cases)Check([[[TFAIReasoningOptions(@{@"protocol":c[0],@"model":c[1]}) valueForKey:@"id"] copy] isEqual:c[2]],@"declarative reasoning retains old exact menu");
 NSArray *skills=[TFAIAgentContext skills:root];Check(skills.count==11,@"eleven plugin development and reverse analysis text skills");NSString *meta=[TFAIAgentContext metadata:root];Check([meta containsString:@"theos-logos"]&&![meta containsString:@"%hook TARGET_CLASS"],@"metadata contains no unused skill body");for(NSDictionary *skill in skills){NSDictionary *loaded=[TFAIAgentContext readSkill:skill[@"id"] root:root error:nil];Check([loaded[@"body"] length]>0&&[loaded[@"readOnly"] boolValue]&&![loaded[@"scriptsExecuted"] boolValue],@"each professional skill loads as read-only text on demand");Check(![meta containsString:loaded[@"body"]],@"skill directory never embeds full skill body");}Check(![meta containsString:@"ADRP"]&&![meta containsString:@"lifecycleExecutionObserved"]&&![meta containsString:@"nextEntry 就是精确末尾"],@"reverse and FLEX instructions remain outside metadata-only context");Check([TFAIAgentContext installSkills:root error:nil],@"install skills to project directory");Check([[TFAIAgentContext skills:root].firstObject[@"source"] isEqual:@"project"],@"project skills preferred");
 NSString *skillPath=[root stringByAppendingPathComponent:@".dylix/skills/theos-logos/SKILL.md"];Write(skillPath,@"---\nname: Custom\ndescription: User preserved\n---\nOriginal body");Check([TFAIAgentContext installSkills:root error:nil],@"reinstall skips existing skill folders");Check([[TFAIAgentContext readSkill:@"theos-logos" root:root error:nil][@"body"] containsString:@"Original body"],@"existing skill body preserved");Check([TFAIAgentContext readSkill:@"../secret" root:root error:nil]==nil,@"skill traversal rejected");
 NSString *outside=[root.stringByDeletingLastPathComponent stringByAppendingPathComponent:@"external-skill"];Write([outside stringByAppendingPathComponent:@"SKILL.md"],@"---\nname: External\ndescription: outside\n---\nsecret");[fm createSymbolicLinkAtPath:[root stringByAppendingPathComponent:@".dylix/skills/external"] withDestinationPath:outside error:nil];Check([TFAIAgentContext readSkill:@"external" root:root error:nil]==nil,@"skill symlink escape rejected");
 Check([[TFAIAgentContext memory:root error:nil] isEqual:@""],@"missing memory starts empty without overwrite");Check([TFAIAgentContext saveMemory:@"Confirmed SDK 16.4" root:root expected:[TFAIAgentContext fingerprint:@""] error:nil],@"explicit memory edit persists");Check([[TFAIAgentContext memory:root error:nil] isEqual:@"Confirmed SDK 16.4"],@"memory round-trip");Check(![TFAIAgentContext saveMemory:@"lost" root:root expected:[TFAIAgentContext fingerprint:@""] error:nil],@"concurrent memory edit rejected");
 NSMutableArray *messages=[NSMutableArray new];for(int i=0;i<44;i++){[messages addObject:@{@"role":@"user",@"content":[NSString stringWithFormat:@"message %d",i]}];[messages addObject:@{@"role":@"assistant",@"content":@"record"}];}NSString *session=NSUUID.UUID.UUIDString;NSArray *compacted=[TFAIAgentContext compact:messages root:root session:session error:nil];Check(compacted.count==16&&[compacted.firstObject[@"role"] isEqual:@"user"],@"long context retains 8 complete user turns");Check(messages.count==88,@"public conversation unchanged");Check([fm fileExistsAtPath:[[root stringByAppendingPathComponent:@".dylix/summaries"] stringByAppendingPathComponent:[session stringByAppendingString:@".md"]]],@"local summary stored");Check(![[compacted description] containsString:@"本地会话摘要"],@"summary never added to outgoing context");
 for(NSString *name in @[@"write_file",@"build_project",@"git_push",@"execute_shell",@"query_delete"]){Check(![TFAIMCP readOnlyTool:@{@"name":name,@"annotations":@{@"readOnlyHint":@YES,@"destructiveHint":@NO}}],@"MCP mutation names blocked despite annotations");}Check([TFAIMCP readOnlyTool:@{@"name":@"search_docs",@"annotations":@{@"readOnlyHint":@YES,@"destructiveHint":@NO}}],@"MCP read-only query classified");Check(![TFAIMCP readOnlyTool:@{@"name":@"query"}],@"missing MCP annotations fail closed");Check(![TFAIMCP.shared importJSON:@"{\"mcpServers\":{\"bad\":{\"command\":\"sh\"}}}" error:nil],@"MCP stdio rejected");Check(![TFAIMCP.shared importJSON:@"{\"mcpServers\":{\"bad\":{\"url\":\"https://host/mcp?token=secret\"}}}" error:nil],@"MCP URL credential/query import rejected");
 [fm removeItemAtPath:[root stringByAppendingPathComponent:@".dylix/skills/external"] error:nil];NSString *source=[root stringByAppendingPathComponent:@"Tweak.m"],*build=[root stringByAppendingPathComponent:@"build-test"],*cache=[root.stringByDeletingLastPathComponent stringByAppendingPathComponent:@"object-cache"];Write(source,@"int a=1;");Write([build stringByAppendingPathComponent:@"a.o"],@"object fixture");NSDictionary *config=@{@"sdkVersion":@"16.4"};NSString *f=TFAIBuildInputFingerprint(root,config);NSArray *args=@[@"clang",source,@"-o",[build stringByAppendingPathComponent:@"a.o"]];TFAIBuildSaveObject(f,args,root,build,[build stringByAppendingPathComponent:@"a.o"],cache);[fm removeItemAtPath:[build stringByAppendingPathComponent:@"a.o"] error:nil];Check(TFAIBuildRestoreObject(f,args,root,build,[build stringByAppendingPathComponent:@"a.o"],cache),@"verified object checkpoint resumes");Write(source,@"int a=2;");Check(![TFAIBuildInputFingerprint(root,config) isEqual:f],@"source changes invalidate checkpoint");Check(![TFAIBuildInputFingerprint(root,@{@"sdkVersion":@"26.0"}) isEqual:f],@"configuration changes invalidate checkpoint");
 Write([root stringByAppendingPathComponent:@".dylix/forced.h"],@"#define X 1");Check(![TFAIBuildInputFingerprint(root,config) isEqual:f],@"hidden project headers participate in checkpoint fingerprint");
 NSLog(@"TOTAL %d agent extension checks passed",count);return 0;
}}
